function _getValue(address asset, address baseToken, uint256 amount, address[] memory sources)
    internal
    view
    returns (uint256 value)
{
    uint256 initialValue = amount;
    address quotingToken = asset;
    for (uint256 i = 0; i < sources.length; i++) {
        initialValue = _getValue(asset, sources[i], initialValue);
        quotingToken = sources[i];
    }
    return _getValue(quotingToken, baseToken, initialValue);
}

function execute(
    address destination,
    bytes calldata data,
    uint256 gasLimit,
    address executor,
    bytes32[] memory sigR,
    bytes32[] memory sigS,
    uint8[] memory sigV,
    uint256 deadline
) public {
    require(isOwner[msg.sender], "Not an owner");
    require(sigR.length == threshold, "Not enough signatures");
    require(sigR.length == sigS.length && sigR.length == sigV.length, "Lengths do not match");
    require(executor == msg.sender, "Invalid executor");
    require(block.timestamp <= deadline, "Transaction expired");
    {
        bytes32 txInputHash =
            keccak256(abi.encode(TXTYPE_HASH, nonce, destination, data, gasLimit, executor, deadline));
        bytes32 totalHash = keccak256(abi.encodePacked("\x19\x01", _domainSeparatorV4(), txInputHash));
        address lastAdd = address(0);
        for (uint256 i = 0; i < threshold;) {
            address recovered = ECDSA.recover(totalHash, sigV[i], sigR[i], sigS[i]);
            require(recovered > lastAdd && isOwner[recovered]);
            lastAdd = recovered;
            unchecked {
                ++i;
            }
        }

        nonce++;
    }
    emit Execute(destination, data, gasLimit, executor, deadline);
    (bool success,) = destination.call{ gas: gasLimit }(data);
    require(success, "Transaction execution reverted.");
}

function calculateDepositShares(uint256 maxIterations) public onlyManager nonReentrant whenNotPaused {
    uint256 middleTemp = depositQueue.middle;
    uint64 i = 0;

    uint256 oldestUpdateTime = TVLHelper.getLatestUpdateTime(vaultId, registry);

    while (
        depositQueue.last > middleTemp && depositQueue.queue[middleTemp].recordTime <= oldestUpdateTime
            && i < maxIterations
    ) {
        i += 1;
        DepositRequest storage data = depositQueue.queue[middleTemp];

        uint256 shares = previewDeposit(data.amount);
        data.shares = shares;
        data.calculationTime = block.timestamp;
        emit CalculateDeposit(
            middleTemp, data.receiver, block.timestamp, shares, data.amount, shares * 1e18 / data.amount
        );

        middleTemp += 1;
    }

    depositQueue.middle = middleTemp;
}

