    PoolInfo memory pool = abi.decode(PTI.additionalData, (PoolInfo));
    uint256 lpBalance = totalLpBalanceOf(pool);
    (, uint256[] memory _tokenBalances,) = IBalancerVault(balancerVault).getPoolTokens(pool.poolId);
    uint256 _totalSupply = IERC20(pool.pool).totalSupply();

    uint256 _weight = pool.weights[pool.tokenIndex];

    uint256 token1bal = valueOracle.getValue(pool.tokens[pool.tokenIndex], base, _tokenBalances[pool.tokenIndex]);
    return (((1e18 * token1bal * lpBalance) / _weight) / _totalSupply);
}

function makeFlashLoan(IERC20[] memory tokens, uint256[] memory amounts, bytes memory userData)
    external
    nonReentrant
{
    caller = msg.sender;
    emit MakeFlashLoan(tokens, amounts);
    vault.flashLoan(this, tokens, amounts, userData);
    caller = address(0);
}

function receiveFlashLoan(
    IERC20[] memory tokens,
    uint256[] memory amounts,
    uint256[] memory feeAmounts,
    bytes memory userData
) external override {
    emit ReceiveFlashLoan(tokens, amounts, feeAmounts, userData);
    require(msg.sender == address(vault));
    (
        uint256 vaultId,
        address receiver,
        address[] memory destinationConnector,
        bytes[] memory callingData,
        uint256[] memory gas
    ) = abi.decode(userData, (uint256, address, address[], bytes[], uint256[]));
    (,,, address keeperContract,, address emergencyManager) = registry.getGovernanceAddresses(vaultId);
    if (!(caller == keeperContract)) {
        revert Unauthorized(caller);
    }
    if (registry.isAnActiveConnector(vaultId, receiver)) {
        for (uint256 i = 0; i < tokens.length; i++) {
            // send the tokens to the receiver
            tokens[i].safeTransfer(receiver, amounts[i]);
            amounts[i] = amounts[i] + feeAmounts[i];
        }
        for (uint256 i = 0; i < destinationConnector.length; i++) {
            // execute the transactions
            (bool success,) = destinationConnector[i].call{ value: 0, gas: gas[i] }(callingData[i]);
            require(success, "BalancerFlashLoan: Flash loan failed");
        }
        for (uint256 i = 0; i < tokens.length; i++) {
            // send the tokens back to this contract
            BaseConnector(receiver).sendTokensToTrustedAddress(address(tokens[i]), amounts[i], address(this), "");
        }
    }
    for (uint256 i = 0; i < tokens.length; i++) {
        // send the tokens back to the vault
        tokens[i].safeTransfer(msg.sender, amounts[i]);
        require(tokens[i].balanceOf(address(this)) == 0, "BalancerFlashLoan: Flash loan extra tokens");
    }
}

function calculateDepositShares(uint256 maxIterations) public onlyManager nonReentrant whenNotPaused {
    uint256 middleTemp = depositQueue.middle;
    uint64 i = 0;

    uint256 oldestUpdateTime = TVLHelper.getLatestUpdateTime(vaultId, registry);

    while (
        depositQueue.last > middleTemp && depositQueue.queue[middleTemp].recordTime <= oldestUpdateTime
            && i < maxIterations
    ) {
        i += 1;
        DepositRequest storage data = depositQueue.queue[middleTemp];

        uint256 shares = previewDeposit(data.amount);
        data.shares = shares;
        data.calculationTime = block.timestamp;
        emit CalculateDeposit(
            middleTemp, data.receiver, block.timestamp, shares, data.amount, shares * 1e18 / data.amount
        );

        middleTemp += 1;
    }

    depositQueue.middle = middleTemp;
}

function calculateWithdrawShares(uint256 maxIterations) public onlyManager nonReentrant whenNotPaused {
    uint256 middleTemp = withdrawQueue.middle;
    uint64 i = 0;
    uint256 processedShares = 0;
    uint256 assetsNeededForWithdraw = 0;
    uint256 oldestUpdateTime = TVLHelper.getLatestUpdateTime(vaultId, registry);

    if (currentWithdrawGroup.isFullfilled == false && currentWithdrawGroup.isStarted == true) {
        revert NoyaAccounting_ThereIsAnActiveWithdrawGroup();
    }
    while (
        withdrawQueue.last > middleTemp && withdrawQueue.queue[middleTemp].recordTime <= oldestUpdateTime
            && i < maxIterations
    ) {
        i += 1;
        WithdrawRequest storage data = withdrawQueue.queue[middleTemp];
        uint256 assets = previewRedeem(data.shares);
        data.amount = assets;
        data.calculationTime = block.timestamp;
        assetsNeededForWithdraw += assets;
        processedShares += data.shares;
        emit CalculateWithdraw(middleTemp, data.owner, data.receiver, data.shares, assets, block.timestamp);

        middleTemp += 1;
    }
    currentWithdrawGroup.totalCBAmount += assetsNeededForWithdraw;
    withdrawQueue.middle = middleTemp;
}

